import os, re, json, glob, hashlib, math

BASE = "storage/shared/atlas/analysis/inquirer_veritas_power_law_sim"

def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for b in iter(lambda: f.read(1<<20), b""):
            h.update(b)
    return h.hexdigest()

def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, indent=2, ensure_ascii=False)

def parse_ver(ver_str):
    parts = [int(x) for x in ver_str.split(".")]
    if len(parts) == 2:
        parts.append(0)
    return tuple(parts)

# Find latest v4.6.x summary
cand = []
for p in glob.glob(os.path.join(BASE, "power_law_sim_summary_v4.6*_avg.json")):
    m = re.search(r"power_law_sim_summary_v(4\.6(?:\.\d+)?)_avg\.json$", os.path.basename(p))
    if m:
        cand.append((parse_ver(m.group(1)), m.group(1), p))
cand.sort()
latest = cand[-1] if cand else None

status = {}
if not latest:
    found = sorted([os.path.basename(x) for x in glob.glob(os.path.join(BASE, "*v4.6*"))])[:50]
    status = {"state": "waiting_for_summary", "found": found}
else:
    ver_str = latest[1]  # e.g., "4.6.2"
    summary = latest[2]
    stem = f"v{ver_str}_avg"
    csv = os.path.join(BASE, f"power_law_sim_output_{stem}.csv")
    png = os.path.join(BASE, f"power_law_sim_{stem}_plot.png")
    strict_out = os.path.join(BASE, f"verify_config_v{ver_str}.strict.json")
    tol_out = os.path.join(BASE, f"verify_config_v{ver_str}.tolerance.json")
    readme = os.path.join(BASE, f"README_VERIFICATION_v{ver_str}.md")

    # Strict config
    outs, sha_list = [], []
    for path in [summary, png, csv]:
        if os.path.exists(path):
            s = sha256(path)
            outs.append({"path": path, "sha256": s})
            sha_list.append({"path": path, "sha256": s})
    if outs:
        write_json(strict_out, {"env": {"python": "3.10", "deps": []}, "data": [], "outputs": outs})
        # README
        lines = [f"# v{ver_str} Verification (Strict, Auto-Packaged)", "", "Artifacts:"]
        for o in outs: lines.append(f"- {o['path']}")
        lines += ["", "Strict config:", f"- {strict_out}", "", "One-line verify:",
                  f"- python storage/shared/agency_lab/repro_template/v2/verify.py --mode strict --config " + strict_out,
                  "", "SHA256:"]
        for sh in sha_list: lines.append(f"- {sh['path']} → {sh['sha256']}")
        with open(readme, "w", encoding="utf-8") as f: f.write("\n".join(lines) + "\n")

    # Tolerance config (~2×SE + rtol)
    METRIC_MAP = [
        ("avg_cycle_metrics.num_void_cycles_detected", "num_void_cycles_detected", "std_cycle_metrics.num_void_cycles_detected"),
        ("avg_cycle_metrics.cycle_len_mean", "cycle_len_mean", "std_cycle_metrics.cycle_len_mean"),
        ("avg_cycle_metrics.cycle_len_cv", "cycle_len_cv", "std_cycle_metrics.cycle_len_cv"),
        ("avg_cycle_metrics.stability_score", "stability_score", "std_cycle_metrics.stability_score"),
        ("avg_cycle_metrics.percent_time_in_void", "percent_time_in_void", "std_cycle_metrics.percent_time_in_void"),
        ("avg_cycle_metrics.depth_mean", "depth_mean", "std_cycle_metrics.depth_mean"),
        ("avg_cycle_metrics.depth_min", "depth_min", "std_cycle_metrics.depth_min"),
        ("avg_final_meta_edge_score", "avg_final_meta_edge_score", "std_final_meta_edge_score"),
    ]
    def get(js, dotted, default=None):
        cur = js
        for k in dotted.split("."):
            if isinstance(cur, dict) and k in cur:
                cur = cur[k]
            else:
                return default
        return cur
    tol_info = None
    if os.path.exists(summary):
        js = json.load(open(summary, "r", encoding="utf-8"))
        n = int(js.get("num_runs") or 1); sr = max(1, n)
        metrics = {}
        for avg_key, name, std_key in METRIC_MAP:
            avg = get(js, avg_key, None)
            if avg is None: continue
            std = get(js, std_key, None)
            if std is None:
                atol = 0.2 * abs(float(avg))
            else:
                se = float(std) / math.sqrt(sr)
                atol = 2.0 * se
            metrics[name] = {"mode": "tolerance", "target": float(avg), "atol": float(atol), "rtol": 0.2}
        write_json(tol_out, {"env": {"python": "3.10", "deps": []}, "data": [], "outputs": [{"path": summary, "metrics": metrics}]})
        tol_info = {"written": tol_out, "metrics": len(metrics)}

    status = {
        "state": "packaged",
        "version": ver_str,
        "strict": {"written": strict_out, "sha256": sha_list, "readme": readme} if outs else None,
        "tolerance": tol_info
    }

print(json.dumps(status, indent=2, ensure_ascii=False))

